use Illuminate\Support\Facades\Cache;
$holder = Cache::lock('report', 60);
$holder->get();
$ran = 0;
try {
    Cache::lock('report', 60)->block(0, function () use (&$ran) {
        $ran++;
    });
} catch (Illuminate\Contracts\Cache\LockTimeoutException $e) {
    echo 'timeout:'.$ran;
}
